def last_item_candidates(train, valid_users, sim_items, k=50):
    last_rows = train.sort_values('ts').groupby('user_id').tail(1)
    last_item = pd.Series(last_rows['item_id'].values, index=last_rows['user_id'])
    rows = []
    for user in valid_users:
        item = last_item.get(user)
        for cand in sim_items.get(item, [])[:k]:
            rows.append({'user_id': user, 'item_id': cand})
    return pd.DataFrame(rows)

def add_hard_negatives(train, positives, k=1):
    popular = train['item_id'].value_counts().index.tolist()
    seen = train.groupby('user_id')['item_id'].apply(set).to_dict()
    rows = []
    for _, row in positives.iterrows():
        user = row['user_id']
        forbidden = seen.get(user, set()) | {row['item_id']}
        picked = [item for item in popular if item not in forbidden][:k]
        rows += [{'user_id': user, 'item_id': item, 'label': 0} for item in picked]
    return pd.DataFrame(rows)

def mean_recall_at_k(pred_by_user, true_by_user, k):
    scores = []
    for user, relevant in true_by_user.items():
        relevant = set(relevant)
        if not relevant:
            continue
        recommended = pred_by_user.get(user, [])[:k]
        hits = len(set(recommended) & relevant)
        scores.append(hits / len(relevant))
    return float(np.mean(scores)) if scores else 0.0

def map_at_k(pred_by_user, true_by_user, k):
    scores = []
    for user, relevant in true_by_user.items():
        relevant = set(relevant)
        if not relevant:
            continue
        hits = 0
        score = 0.0
        for rank, item in enumerate(pred_by_user.get(user, [])[:k], start=1):
            if item in relevant:
                hits += 1
                score += hits / rank
        scores.append(score / min(len(relevant), k))
    return float(np.mean(scores)) if scores else 0.0

def best_f1_threshold(y_true, prob):
    best_t, best_score = 0.5, -1
    for t in np.linspace(0.01, 0.99, 99):
        pred = (prob >= t).astype(int)
        score = f1_score(y_true, pred)
        if score > best_score:
            best_t, best_score = t, score
    return best_t, best_score
